             #{postId}, #{userId}, #{content}, SYSDATE
         )

mapper.select:
SELECT comment_id, post_id, user_id, content, created_at, deleted_at, nickname, author_name, profile_img, post_title FROM ( SELECT c.comment_id, c.post_id, c.user_id, c.content, c.created_at, c.deleted_at, COALESCE(u.nickname, u.name, '익명') as nickname, COALESCE(u.nickname, u.name, '익명') as author_name, u.profile_img, p.title as post_title, ROW_NUMBER() OVER (ORDER BY c.created_at DESC) as rnum FROM comments c LEFT JOIN users u ON c.user_id = u.user_id AND u.deleted_at IS NULL LEFT JOIN posts p ON c.post_id = p.post_id WHERE c.deleted_at IS NULL
AND ( c.content LIKE '%' || #{search} || '%' OR COALESCE(u.nickname, u.name) LIKE '%' || #{search} || '%' OR p.title LIKE '%' || #{search} || '%' )
) WHERE rnum > #{offset} AND rnum <= #{offset} + #{size} ORDER BY created_at DESC
